  ["feature.extra-attack.xphb2024.ranger.base.5"]={title="Extra Attack",subtitle="Caracteristica - XPHB - 2024",body="Pagina: 120\n\nYou can attack twice instead of once whenever you take the XPHB action on your turn."},
